changeSet.sql:
ALTER TABLE cbam_subinstallation_migration
    ADD CONSTRAINT chk_cbam_migration_status
        CHECK (
            migration_status IN (
                                 'PENDING',
                                 'COMPLETED',
                                 'FAILED'
                )
            );

ALTER TABLE cbam_subinstallation_migration
    ADD CONSTRAINT chk_cbam_source_target_mapping
        CHECK (
            (
                source_value = 'HYDROGEN'
                    AND target_value IN (
                                         'HYDROGEN_CBAM',
                                         'HYDROGEN_NON_CBAM'
                    )
                )
                OR (
                source_value = 'IRON_CASTING'
                    AND target_value IN (
                                         'IRON_CASTING_CBAM',
                                         'IRON_CASTING_NON_CBAM'
                    )
                )
                OR (
                source_value = 'HEAT_BENCHMARK_CL'
                    AND target_value IN (
                                         'HEAT_BENCHMARK_CL_CBAM',
                                         'HEAT_BENCHMARK_CL_NON_CBAM'
                    )
                )
                OR (
                source_value = 'FUEL_BENCHMARK_CL'
                    AND target_value IN (
                                         'FUEL_BENCHMARK_CL_CBAM',
                                         'FUEL_BENCHMARK_CL_NON_CBAM'
                    )
                )
                OR (
                source_value = 'PROCESS_EMISSIONS_CL'
                    AND target_value IN (
                                         'PROCESS_EMISSIONS_CL_CBAM',
                                         'PROCESS_EMISSIONS_CL_NON_CBAM'
                    )
                )
            );
